types.001_cop0:
/* COP0 $22: non-zero when a hardware debugger (DTL-T) is attached */
static inline u32 getCop0Reg22(void) {
    u32 v;
    __asm__ __volatile__("mfc0 %0, $22" : "=r"(v));
    return v;
}

types.00_typedefs:
typedef int SceMode;
typedef s64 SceOff;
typedef s32 SceSSize;
typedef struct SceIoStat SceIoStat;
typedef struct SceIoDirent SceIoDirent;
typedef struct SceIoIob SceIoIob;
