types.01_SceIoStat:
typedef struct {
    u16 year; /* 0x0 */
    u16 month; /* 0x2 */
    u16 day; /* 0x4 */
    u16 hour; /* 0x6 */
    u16 minute; /* 0x8 */
    u16 second; /* 0xA */
    u32 microsecond; /* 0xC */
} ScePspDateTime;

/* 0x58 bytes */
struct SceIoStat {
    SceMode st_mode; /* 0x0 */
    u32 st_attr; /* 0x4 */
    SceOff st_size; /* 0x8 */
    ScePspDateTime st_ctime; /* 0x10 */
    ScePspDateTime st_atime; /* 0x20 */
    ScePspDateTime st_mtime; /* 0x30 */
    u32 st_private[6]; /* 0x40 */
};

types.11_LFlashSegment:
typedef struct LFlashSegment LFlashSegment;
/* lflash segment, 0x1C bytes */
struct LFlashSegment {
    u8 pad0[0x4];
    u16 firstLbn; /* 0x4 */
    u8 pad6[0x2];
    u16 maxLbn; /* 0x8 */
    u8 padA[0x2];
    u16 *lpTable; /* 0xC */
    u8 pad10[0xC];
};

types.12_LFlashDev:
typedef struct LFlashDev LFlashDev;
/* lflash device state (D_0000EED0), reboot 1.00: at least 0x1D4 bytes (lfatfs 1.00: 0x1C8) */
struct LFlashDev {
    u8 pad0[0x18C];
    u32 pageSize; /* 0x18C */
    s32 pageShift; /* 0x190 */
    u32 pagesPerBlock; /* 0x194 */
    u8 pad198[0x14];
    u32 nSegments; /* 0x1AC */
    LFlashSegment *segments; /* 0x1B0 */
    s32 unk1B4; /* 0x1B4 */
    u8 *blockBuf; /* 0x1B8 */
    void *unk1BC; /* 0x1BC */
    void *unk1C0; /* 0x1C0 */
    void *unk1C4; /* 0x1C4 */
    u32 unk1C8; /* 0x1C8 */
    u32 unk1CC; /* 0x1CC */
    u16 unk1D0; /* 0x1D0 */
    u16 unk1D2; /* 0x1D2 */
};

types.13_LFlashPart:
typedef struct LFlashPart LFlashPart;
/* lflash partition (iob->i_private of lflash0:), size unknown */
struct LFlashPart {
    u8 pad0[0x4];
    u32 unk4; /* 0x4 */
    u8 pad8[0x4];
    u32 unkC; /* 0xC */
};

types.14_LFlashDevInfo:
typedef struct LFlashDevInfo LFlashDevInfo;
/* ioctl 0x3D001 output (0x44 bytes); fields 0x10..0x20 copied to UFatUnit.devInfo */
struct LFlashDevInfo {
    u8 pad0[0x10];
    u32 unk10; /* 0x10 */
    u32 unk14; /* 0x14 */
    u32 unk18; /* 0x18 */
    u32 unk1C; /* 0x1C */
    u32 flags; /* 0x20 */
    u8 pad24[0x20];
};

types.15_UFatNode:
typedef struct UFatNode UFatNode;
/* open file/dir node (0x54 bytes); lists D_0000D60C (head) / D_0000D610 (tail), free list D_0000D614 */
struct UFatNode {
    struct UFatNode *next; /* 0x0 */
    struct UFatNode *prev; /* 0x4 */
    UFatUnit *unit; /* 0x8 */
    u32 startCluster; /* 0xC */
    s32 size; /* 0x10 */
    s32 pos; /* 0x14 */
    s32 clusterOff; /* 0x18 */
    s32 curCluster; /* 0x1C */
    u8 pad20[0x4];
    FatDirEntry dirent; /* 0x24 */
    u8 pad44[0x10];
};

types.16_UFatBuf:
typedef struct UFatBuf UFatBuf;
/* sector buffer cache entry (buf_lookup), size unknown */
struct UFatBuf {
    u8 pad0[0x14];
    u8 *data; /* 0x14 */
};

types.20_SceNandInfo:
/* NAND chip geometry (D_00018BCC); filled by sceNandDetectChip */
typedef struct {
    u32 pageSize; /* 0x0 */
    u32 pagesPerBlock; /* 0x4 */
    u32 totalBlocks; /* 0x8 */
    u8 makerId; /* 0xC */
    u8 deviceId; /* 0xD */
    u8 padE[2];
} SceNandInfo;
/* known chip table entry (D_00016C14, 17 entries) */
typedef struct {
    u8 makerId; /* 0x0 */
    u8 deviceId; /* 0x1 */
    u16 pageSize; /* 0x2 */
    u16 pagesPerBlock; /* 0x4 */
    u16 unk6;
    u32 totalBlocks; /* 0x8 */
} SceNandChipEntry;

