types.22_Elf32:
/* standard ELF32 structures (loadelf.c) */
typedef struct {
    u8 e_ident[16]; /* 0x0 */
    u16 e_type; /* 0x10, 0xFFA0 = PRX */
    u16 e_machine; /* 0x12 */
    u32 e_version; /* 0x14 */
    u32 e_entry; /* 0x18 */
    u32 e_phoff; /* 0x1C */
    u32 e_shoff; /* 0x20 */
    u32 e_flags; /* 0x24 */
    u16 e_ehsize; /* 0x28 */
    u16 e_phentsize; /* 0x2A */
    u16 e_phnum; /* 0x2C */
    u16 e_shentsize; /* 0x2E */
    u16 e_shnum; /* 0x30 */
    u16 e_shstrndx; /* 0x32 */
} Elf32_Ehdr;
typedef struct {
    u32 p_type; /* 0x0 */
    u32 p_offset; /* 0x4 */
    u32 p_vaddr; /* 0x8 */
    u32 p_paddr; /* 0xC */
    u32 p_filesz; /* 0x10 */
    u32 p_memsz; /* 0x14 */
    u32 p_flags; /* 0x18 */
    u32 p_align; /* 0x1C */
} Elf32_Phdr;
typedef struct {
    u32 sh_name; /* 0x0 */
    u32 sh_type; /* 0x4 */
    u32 sh_flags; /* 0x8 */
    u32 sh_addr; /* 0xC */
    u32 sh_offset; /* 0x10 */
    u32 sh_size; /* 0x14 */
    u32 sh_link; /* 0x18 */
    u32 sh_info; /* 0x1C */
    u32 sh_addralign; /* 0x20 */
    u32 sh_entsize; /* 0x24 */
} Elf32_Shdr;
typedef struct {
    u32 r_offset; /* 0x0 */
    u32 r_info; /* 0x4 */
} Elf32_Rel;

types.SceIoDeviceEntry:
/* 1.00: 8 bytes (no d_userfd_count yet). */
struct SceIoDeviceEntry {
    SceIoDeviceTable *d_dp; /* 0x0 */
    void *d_private; /* 0x4 */
};

types.SceIoDeviceTable:
